@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea class="form-control mb-3" rows="12" @bind="content" @bind:event="oninput"></textarea>

<div class="d-flex align-items-center gap-3 mb-3">
    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
    <button class="btn btn-outline-danger" @onclick="ClearAsync">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSavedAt;
    private IJSObjectReference? module;
    private Timer? autoSaveTimer;

    private bool HasUnsavedChanges => content != savedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        module = await JS.InvokeAsync<IJSObjectReference>(
            "import", "./Components/Pages/Notepad.razor.js");

        var restored = await module.InvokeAsync<string?>("load");
        if (!string.IsNullOrEmpty(restored))
        {
            content = restored;
            savedContent = restored;
            StateHasChanged();
        }

        await module.InvokeVoidAsync("enableBeforeUnload");

        autoSaveTimer = new Timer(async _ =>
        {
            if (HasUnsavedChanges)
            {
                await InvokeAsync(async () =>
                {
                    await SaveAsync();
                    StateHasChanged();
                });
            }
        }, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
    }

    private async Task SaveAsync()
    {
        if (module is null) return;
        await module.InvokeVoidAsync("save", content);
        savedContent = content;
        lastSavedAt = DateTime.Now;
        await module.InvokeVoidAsync("setDirty", false);
    }

    private async Task SaveNowAsync()
    {
        await SaveAsync();
    }

    private async Task ClearAsync()
    {
        content = string.Empty;
        savedContent = string.Empty;
        lastSavedAt = null;
        if (module is not null)
        {
            await module.InvokeVoidAsync("clear");
            await module.InvokeVoidAsync("setDirty", false);
        }
    }

    protected override async Task OnAfterRenderAsync_UpdateDirty()
    {
        // This won't be called — we handle dirty flag in save/clear explicitly.
    }

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
        {
            await autoSaveTimer.DisposeAsync();
        }
        if (module is not null)
        {
            await module.InvokeVoidAsync("setDirty", false);
            await module.DisposeAsync();
        }
    }
}

const storageKey = "notepad-content";

let dirty = false;

function beforeUnloadHandler(e) {
    if (dirty) {
        e.preventDefault();
    }
}

export function enableBeforeUnload() {
    window.addEventListener("beforeunload", beforeUnloadHandler);
}

export function setDirty(value) {
    dirty = value;
}

export function save(content) {
    localStorage.setItem(storageKey, content);
}

export function load() {
    return localStorage.getItem(storageKey);
}

export function clear() {
    localStorage.removeItem(storageKey);
}

